// Actual transport control: all requests stay on the isolated local origin.
async function profileApi(page, responses=[]){
 const state={calls:[],responses:[...responses],held:[],scores:[]};
 await page.route('**/api/scores.php',async route=>{
  const req=route.request(),p=req.method()==='POST'?req.postDataJSON():{};
  if(p.action!=='update_profile'){return route.fulfill({contentType:'application/json',body:JSON.stringify({ok:true,scores:state.scores})});}
  state.calls.push(p);const action=state.responses.shift()||{};
  const reply=async (a={})=>{if(a.abort)return route.abort('failed');const body=a.raw??JSON.stringify(a.data??{ok:true,source:'mysql',mode:p.mode,...(p.mode==='rename'?{uniquenessVerified:true,playerName:p.playerName}:{hideTelegram:p.hideTelegram})});return route.fulfill({status:a.status||200,contentType:'application/json',body});};
  if(action.hold){await new Promise(resolve=>state.held.push(async a=>{await reply(a);resolve();}));}else await reply(action);
 });return state;
}
async function waitCalls(page,state,n){await page.waitForFunction(()=>true);for(let i=0;i<100&&state.calls.length<n;i++)await page.waitForTimeout(20);assert.equal(state.calls.length,n);}
async function release(state,reply){assert.ok(state.held.length,'No held request');await state.held.shift()(reply);}
