async function pageCase(name,options,fn){await check(name,async()=>{const page=await newPage({social:true,...options});try{return await fn(page);}finally{await page.close();}});}
function methodRange(source,name){const start=source.indexOf(`  ${name}(`)>=0?source.indexOf(`  ${name}(`):source.indexOf(`  async ${name}(`);assert.ok(start>=0,name);const end=source.slice(start+2).search(/\n  (?:async )?[a-zA-Z_$][\w$]*\(/);return{start,end:end<0?source.indexOf('\n}\n',start):start+2+end};}
function stripMethods(s,names){for(const name of names){const r=methodRange(s,name);s=s.slice(0,r.start)+`  /*allowed:${name}*/`+s.slice(r.end);}return s;}
